using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel.Connectors.HuggingFace;
using Microsoft.SemanticKernel.Connectors.HuggingFace.Core;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Connectors.HuggingFace.Tests
{
    public class HuggingFaceEmbeddingGeneratorTests
    {
        [Fact]
        public void Dispose_ShouldDisposeHttpClient_WhenHttpClientIsNotExternal()
        {
            // Arrange
            var mockHttpClient = new Mock<HttpClient>();
            var generator = new HuggingFaceEmbeddingGenerator(
                modelId: "test-model",
                endpoint: new Uri("http://test-endpoint"),
                apiKey: "test-api-key",
                httpClient: null,
                loggerFactory: null);

            // Act
            generator.Dispose();

            // Assert
            mockHttpClient.Verify(client => client.Dispose(), Times.Once);
        }

        [Fact]
        public void Dispose_ShouldNotDisposeHttpClient_WhenHttpClientIsExternal()
        {
            // Arrange
            var mockHttpClient = new Mock<HttpClient>();
            var generator = new HuggingFaceEmbeddingGenerator(
                modelId: "test-model",
                endpoint: new Uri("http://test-endpoint"),
                apiKey: "test-api-key",
                httpClient: mockHttpClient.Object,
                loggerFactory: null);

            // Act
            generator.Dispose();

            // Assert
            mockHttpClient.Verify(client => client.Dispose(), Times.Never);
        }
    }
}
```

I see that the issue is with the `Dispose` method of `HttpClient` not being mockable directly using Moq. We need to mock the behavior of `HttpClient` differently. Let's use a different approach by creating a subclass of `HttpClient` and overriding the `Dispose` method.

